   572|
   573|/**
   574| * Sync a runtime-present variable's value into the Render service env (the real
   575| * injection path for the backend runtime). Reads the value from THIS runtime and
   576| * writes it to the Render service via the Render API; never accepts or echoes the
   577| * value over the wire. Returns honest success/failure.
   578| */
   579|export async function syncVariableToRender(
   580|  name: string,
   581|  env: EnvSnapshot = process.env,
   582|  fetchImpl: FetchLike = fetch,
   583|): Promise<{ ok: boolean; httpStatus: number | null; detail: string }> {
   584|  const spec = RUNTIME_VARIABLE_SPECS.find((s) => s.name === name);
   585|  if (!spec) return { ok: false, httpStatus: null, detail: 'Unknown variable.' };
   586|
   587|  const { value } = resolveValue(env, spec);
   588|  if (value.length === 0) {
   589|    return { ok: false, httpStatus: null, detail: `${name} is not present in this runtime, so there is nothing to sync. Set it in the source scope first.` };
   590|  }
   591|
   592|  const key = trimmed(env.RENDER_API_KEY);
   593|  const serviceId = trimmed(env.RENDER_SERVICE_ID);
   594|  if (!key || !serviceId) {
   595|    return { ok: false, httpStatus: null, detail: 'RENDER_API_KEY + RENDER_SERVICE_ID required to sync into the Render runtime.' };
   596|  }
   597|
   598|  const r = await probe(
   599|    fetchImpl,
   600|    `https://api.render.com/v1/services/${encodeURIComponent(serviceId)}/env-vars/${encodeURIComponent(name)}`,
